(5567185, 805440, 99981, '<td valign="top">This boot would be a fine theme for the Personification Challenge :). It reminds me of predator mouth. I like this old style created by this colors and the macro is really nice. Maybe i didn''t get your intention with this image, but i like it! Good luck!</td>', 'This boot would be a fine theme for the Personification Challenge :). It reminds me of predator mouth. I like this old style created by this colors and the macro is really nice. Maybe i didn''t get your intention with this image, but i like it! Good luck!', '2009-07-09 20:26:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5567186, 805318, 99981, '<td valign="top">Simple but fine...I really like this shot! Good luck!</td>', 'Simple but fine...I really like this shot! Good luck!', '2009-07-09 20:26:17.000000', NULL, 1),
(5567188, 804317, 99981, '<td valign="top">Nice colors! Good shot!</td>', 'Nice colors! Good shot!', '2009-07-09 20:26:40.000000', NULL, 1),
(5567192, 805333, 99981, '<td valign="top">Good choice of color and nice catch..the boots just look a little hidden in my opinion, but that is not very significant. Good luck!</td>', 'Good choice of color and nice catch..the boots just look a little hidden in my opinion, but that is not very significant. Good luck!', '2009-07-09 20:27:34.000000', NULL, 1),
(5567193, 804021, 99981, '<td valign="top">Nice shot! Well composed with nice colors and a good DoF...i hope you do well! Good luck!</td>', 'Nice shot! Well composed with nice colors and a good DoF...i hope you do well! Good luck!', '2009-07-09 20:27:45.000000', NULL, 1),
(5567194, 805289, 99981, '<td valign="top">Great light, i think it helped a lot to give a delicate image to those feet. The dry leaves are great too! I wish there was more colors and just a little brighter! Good luck, nice shot!</td>', 'Great light, i think it helped a lot to give a delicate image to those feet. The dry leaves are great too! I wish there was more colors and just a little brighter! Good luck, nice shot!', '2009-07-09 20:27:48.000000', NULL, 1),
(5567195, 804579, 99981, '<td valign="top">I really like the idea, border and colors, but i think the light is a little harsh at some parts of the girl shoes, and the guy shoes are kind of hidden. Maybe another perspective and less white would be great! Good luck to you!</td>', 'I really like the idea, border and colors, but i think the light is a little harsh at some parts of the girl shoes, and the guy shoes are kind of hidden. Maybe another perspective and less white would be great! Good luck to you!', '2009-07-09 20:27:51.000000', NULL, 1),
(5567197, 805268, 99981, '<td valign="top">Nice shot, really well composed...i''m not sure about the prime object because i''m leaning to look at their hands..still, i think it''s a nice shot for this challenge!</td>', 'Nice shot, really well composed...i''m not sure about the prime object because i''m leaning to look at their hands..still, i think it''s a nice shot for this challenge!', '2009-07-09 20:28:10.000000', NULL, 1),
(5567199, 805238, 99981, '<td valign="top">I like the shot in general...you did a nice job with the light, these colors and catching this moment. I just don''t like the border in that image, mainly becase of that black part at the bottom, and some distracting points at the image, like the right leg of the dog in movement...I know that was YOUR choice of perspective, but i think that a closer look at the dog''s face and the sneaker would be perfect in this case.<br/>Sorry if i was rude and for my english! Good luck to you!</td>', 'I like the shot in general...you did a nice job with the light, these colors and catching this moment. I just don''t like the border in that image, mainly becase of that black part at the bottom, and some distracting points at the image, like the right leg of the dog in movement...I know that was YOUR choice of perspective, but i think that a closer look at the dog''s face and the sneaker would be perfect in this case.Sorry if i was rude and for my english! Good luck to you!', '2009-07-09 20:28:27.000000', NULL, 1),
(5567201, 805215, 99981, '<td valign="top">hahha, good idea! I wouldn''t like to meet this Cinderella! I like the shot in general but i would like to see more colors! Good luck to you!</td>', 'hahha, good idea! I wouldn''t like to meet this Cinderella! I like the shot in general but i would like to see more colors! Good luck to you!', '2009-07-09 20:30:14.000000', NULL, 1),
(5567202, 805322, 99981, '<td valign="top">I like this shot and i think you had a good idea, but i really wish to see it much brighter than that! <br/>Good luck to you!</td>', 'I like this shot and i think you had a good idea, but i really wish to see it much brighter than that! Good luck to you!', '2009-07-09 20:30:28.000000', NULL, 1),
(5567203, 804738, 99981, '<td valign="top">I don''t like the border and i think it''s a little too bright, and i almost can''t see the shoes, because the cute girl is the prime object in my opinion. The perspective, colors and the composition are great! Nice shot!<br/>Hope you don''t take my comments on a bad way, it''s just my opinion!<br/>Good luck for you!</td>', 'I don''t like the border and i think it''s a little too bright, and i almost can''t see the shoes, because the cute girl is the prime object in my opinion. The perspective, colors and the composition are great! Nice shot!Hope you don''t take my comments on a bad way, it''s just my opinion!Good luck for you!', '2009-07-09 20:33:16.000000', NULL, 1),
(5567204, 805293, 99981, '<td valign="top">I think the B&amp;W was a good choice, the briefcase, the suit pants and the border gave a nice composition too. The problems in my opinion is that i don''t see a very interesting object and the grass floor doesn''t match with the theme.<br/>Sorry if i was rude...good luck to you!</td>', 'I think the B&W was a good choice, the briefcase, the suit pants and the border gave a nice composition too. The problems in my opinion is that i don''t see a very interesting object and the grass floor doesn''t match with the theme.Sorry if i was rude...good luck to you!', '2009-07-09 20:33:19.000000', NULL, 1),
(5567205, 805312, 99981, '<td valign="top">At least it looks warm! I like the picture in general, it''s really unique...i just wished something more appealing! Sorry if i was rude, ok? Good luck to you!</td>', 'At least it looks warm! I like the picture in general, it''s really unique...i just wished something more appealing! Sorry if i was rude, ok? Good luck to you!', '2009-07-09 20:33:22.000000', NULL, 1),
(5567206, 803929, 99981, '<td valign="top">I''m not giving you a really nice vote because i wish there was a closer look at the boots, instead of this nice composition...the umbrella gave a nice touch to the image, but got too much of my attention! The boots and the water would be enough for me! <br/>Anyway...you did a great work, good luck for you!</td>', 'I''m not giving you a really nice vote because i wish there was a closer look at the boots, instead of this nice composition...the umbrella gave a nice touch to the image, but got too much of my attention! The boots and the water would be enough for me! Anyway...you did a great work, good luck for you!', '2009-07-09 20:33:40.000000', NULL, 1),
