(5567648, 804317, 54645, '<td valign="top">I get the sense of falling rather than flight. I like the overall color scheme and concept. I don''t like the halo around the shoes or the blown out background highlights.</td>', 'I get the sense of falling rather than flight. I like the overall color scheme and concept. I don''t like the halo around the shoes or the blown out background highlights.', '2009-07-10 02:47:27.000000', NULL, 1),
(5567651, 805337, 54645, '<td valign="top">Excellent lighting in my opinion. I like the pose and presentation of the subject, but I think additional attention to the composition would help...a bit to centered for me with the heel of the back shoe "sticking out". The detail of the shoe is fantastic, good choice for the challenge. 6</td>', 'Excellent lighting in my opinion. I like the pose and presentation of the subject, but I think additional attention to the composition would help...a bit to centered for me with the heel of the back shoe "sticking out". The detail of the shoe is fantastic, good choice for the challenge. 6', '2009-07-10 02:50:25.000000', NULL, 1),
(5567655, 805001, 54645, '<td valign="top">I like the DOF, but I don''t get the context of place from the background to complete the story hinted at by the title.</td>', 'I like the DOF, but I don''t get the context of place from the background to complete the story hinted at by the title.', '2009-07-10 02:52:51.000000', NULL, 1),
(5567658, 805354, 54645, '<td valign="top">Funny. The traffic light is the dominant subject based on my interpretation. I like the contrast of color with the blacks and red, although the green grabbed me first.</td>', 'Funny. The traffic light is the dominant subject based on my interpretation. I like the contrast of color with the blacks and red, although the green grabbed me first.', '2009-07-10 02:55:04.000000', NULL, 1),
